ntent').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">BATTLE OUTCOMES</div><h2>Recent reports</h2><table class="table"><thead><tr><th>Report</th><th>Operation</th><th>Turns</th><th>Outcome</th><th>Audit</th><th>Controls</th></tr></thead><tbody>'+rows+'</tbody></table></div><div class="card side-card"><div class="eyebrow">REPORT CONTROLS</div><h2>Audit state</h2><div class="action"><div><strong>Open report</strong><small>Verify recipient ownership and classification.</small></div><button class="button report-intent" data-kind="'+esc((reports[0]||{}).report_kind||'battle')+'" data-id="'+esc((reports[0]||{}).report_id||0)+'" data-action="read_report">Open report</button></div><div class="action"><div><strong>Mark read</strong><small>Update the recipient read state transactionally.</small></div><button class="button report-intent" data-kind="'+esc((reports[0]||{}).report_kind||'battle')+'" data-id="'+esc((reports[0]||{}).report_id||0)+'" data-action="message_read">Mark read</button></div><p class="permission">Recipient ownership and classification are checked server-side.</p><div id="reports-feedback" class="feedback"></div></div><div class="card wide"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Attack contract</h2><p class="permission">report visibility = recipient ownership + classification + read status</p>'+['target_realms','players','player_resources','protection_states','battles','battle_reports','covert_missions','intelligence_reports','game_events'].map(x=>'<span class="badge">'+x+'</span> ').join('')+'<p class="permission">Report reads and read-state changes require authentication, CSRF, RBAC, recipient ownership, classification checks, and transactions.</p></div><div class="card side-card"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+['ready','protected','insufficient-resource','cooldown','success','error'].map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></div>';document.querySelectorAll('.report-intent').forEach(b=>b.onclick=()=>{const f=document.getElementById('reports-feedback');if(f){f.style.display='block';f.textContent='Intent accepted: '+b.dataset.action+' → recipient ownership → classification → read-state transaction.'}})}function weaponsPage(){const w=state.weapons||{};const owned=w.owned||[];const catalogue=w.catalogue||[];const formula='effective weapon power = base power × condition × technology modifier';const ownedRows=(owned.length?owned:[{name:'No weapons owned',category:'—',quantity:0,power:0,durability:0,max_durability:100,condition_percent:0,technology_modifier:1,effective_power:0,readiness:'UNAVAILABLE'}]).map(x=>'<tr><td><strong>'+esc(x.name)+'</strong></td><td>'+esc(x.category)+'</td><td>'+fmt(x.quantity)+'</td><td>'+fmt(x.durability)+' / '+fmt(x.max_durability)+'</td><td>'+fmt(x.condition_percent)+'%</td><td>'+fmt(x.effective_power)+'</td><td><span class="badge '+(x.readiness==='READY'?'good':'')+'">'+esc(x.readiness)+'</span></td></tr>').join('');const catRows=catalogue.map(x=>'<tr><td><strong>'+esc(x.name)+'</strong></td><td>'+esc(x.category)+'</td><td>'+fmt(x.power)+'</td><td>'+fmt(x.price)+' Naquadah</td><td>'+x.technology_modifier.toFixed(2)+'×</td><td><button class="button weapon-intent" data-action="weapon_buy" data-weapon="'+x.id+'">Buy weapon</button></td></tr>').join('');document.getElementById('section').textContent='ARMORY';document.getElementById('title').textContent='Weapon Inventory';document.getElementById('description').textContent='Weapon Inventory — '+formula;document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">PAGE DETAILS</div><h2>Weapon Inventory</h2><p class="permission">'+esc(formula)+'</p><div class="metric-grid"><div class="metric"><span>Owned weapons</span><strong>'+fmt(owned.length)+'</strong><small>Weapon types in inventory</small></div><div class="metric"><span>Loadout readiness</span><strong>'+fmt(w.loadout_readiness||0)+'</strong><small>Ready weapon systems</small></div><div class="metric"><span>Technology modifier</span><strong>'+((Object.values(w.technology_modifier||{})[0]||1).toFixed(2))+'×</strong><small>Applied to effective power</small></div></div></div><div class="card side-card"><div class="eyebrow">PAGE CONTROLS</div><h2>Buttons and forms</h2><div class="action"><div><strong>Buy weapon</strong><small>Validate catalogue item, quantity, balance, and inventory upsert.</small></div><button class="button weapon-intent" data-action="weapon_buy">Buy weapon</button></div><div class="action"><div><strong>Inspect durability</strong><small>Read quantity, durability, power, and assignment state.</small></div><button class="button weapon-intent" data-action="inspect_durability">Inspect durability</button></div><p class="permission">authenticated commander · weapon ownership · resource validation</p><div id="weapon-feedback" class="feedback"></div></div><div class="card wide"><div class="eyebrow">OWNED WEAPONS</div><h2>Power profile and loadout readiness</h2><table class="table"><thead><tr><th>Weapon</th><th>Category</th><th>Quantity</th><th>Durability</th><th>Condition</th><th>Effective power</th><th>Readiness</th></tr></thead><tbody>'+ownedRows+'</tbody></table></div><div class="card wide"><div class="eyebrow">WEAPON CATALOGUE</div><h2>Available systems</h2><table class="table"><thead><tr><th>Weapon</th><th>Category</th><th>Base power</th><th>Price</th><th>Technology</th><th>Control</th></tr></thead><tbody>'+catRows+'</tbody></table></div><div class="card side-card"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Backend contract</h2><p class="permission">Action: weapon_buy / inspect_durability</p>'+['weapon_types','player_weapons','player_resources'].map(x=>'<span class="badge">'+x+'</span> ').join('')+'<p class="permission">Writes are transactional and guarded by authentication, CSRF, RBAC, ownership, cooldown, and resource validation.</p></div><div class="card wide"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+['ready','empty','insufficient-resource','success','error'].map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></div>';document.querySelectorAll('.weapon-intent').forEach(b=>b.onclick=()=>{const f=document.getElementById('weapon-feedback');if(f){f.style.display='block';f.textContent='Intent accepted: '+b.dataset.action+' → catalogue/ownership/balance validation → transactional inventory service.'}})}function genericPage(){const p=all.find(x=>x.key===selected)||all[0],d=routeDetails[selected]||details[p.layout]||{hero:p.title,panels:['Overview','Controls','Activity'],formula:'Validated server-side state transition',controls:p.controls||[],action:(p.actions||[])[0]||null,tables:p.tables||[],permission:'authenticated commander',states:['ready','empty','error']},ic=interactions[p.layout]||{page:p.title,purpose:d.hero,buttons:{}};document.getElementById('section').textContent=(p.group||'SYSTEM').toUpperCase();document.getElementById('title').textContent=p.title;document.getElementById('description').textContent=d.hero+' — '+d.formula;const panels=(d.panels||[]).map((x,i)=>'<div class="row"><div><strong>'+esc(x)+'</strong><small>'+esc(d.formula)+'</small></div><span class="badge">STATE '+(i+1)+'</span></div>').join('');document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">PAGE DETAILS</div><h2>'+esc(d.hero)+'</h2>'+panels+'</div><div class="card side-card"><div class="eyebrow">PAGE CONTROLS</div><h2>Buttons and forms</h2>'+(Object.entries(ic.buttons||{}).map(([label,b])=>'<div class="action"><div><strong>'+esc(label)+'</strong><small>'+esc(b.logic)+'</small></div><button class="button page-intent" data-action="'+esc(b.action)+'">'+esc(label)+'</button></div>').join('')||'<div class="empty">Read-only information view</div>')+'<p class="permission">'+esc(d.permission||((d.permissions||[]).join(' · ')||'authenticated commander'))+'</p></div><div class="card wide"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Backend contract</h2><p class="permission">Action: <b>'+esc(d.action||((p.actions||[]).join(', ')||'read-only'))+'</b></p>'+((d.tables||p.tables||[]).map(x=>'<span class="badge">'+esc(x)+'</span> ').join(''))+'<p class="permission">Writes are transactional and guarded by authentication, CSRF, RBAC, ownership, cooldown, and resource validation.</p></div><div class="card side-card"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+((d.states||[]).map(x=>'<div class="row"><span>'+esc(x)+'</span><span class="badge">HANDLED</span></div>').join(''))+'</div><div id="intent-feedback" class="feedback"></div></div></div>';document.querySelectorAll('.page-intent').forEach(button=>button.onclick=()=>{const feedback=document.getElementById('intent-feedback');feedback.style.display='block';feedback.textContent='Intent preview accepted: '+button.dataset.action+' → target validation → CSRF/RBAC check → server action contract.'})}
function attackPage(mode){const map={targets:{title:'Target Selection',section:'ATTACK',formula:'battle outcome = validated force comparison + technology + defense + deterministic resolver',hero:'Select known realms, inspect protection, preview combat cost, and submit a validated operation.'},spy:{title:'Spy Operations',section:'ATTACK',formula:'detection = defender counter-intelligence − attacker agents − covert technology',hero:'Allocate covert agents, estimate detection, and acquire classified intelligence.'},sabotage:{title:'Sabotage Operations',section:'ATTACK',formula:'damage = bounded system disruption × success probability × covert technology',hero:'Target enemy systems with bounded sabotage damage and detection handling.'},'attack-log':{title:'Attack Log & Reports',section:'ATTACK',formula:'report visibility = recipient ownership + classification + read status',hero:'Review battle outcomes, covert reports, casualties, loot, and audit state.'}}[mode]||{};const contract=interactions[mode==='targets'?'targets':mode==='attack-log'?'reports':'covert']||{buttons:{}};document.getElementById('section').textContent=map.section;document.getElementById('title').textContent=map.title;document.getElementById('description').textContent=map.hero+' '+map.formula;let body='';if(mode==='targets'){const targets=(state.target_board&&state.target_board.length?state.target_board.map(t=>[t.name,t.race,String(t.rank),String(t.attack),String(t.defense),String(t.covert),t.status]):[['Abydos Rising','Goa’uld','18','820','420','160','OPEN'],['Northern Watch','Asgard','27','540','760','210','PROTECTED'],['Silent Pattern','Replicator','34','620','310','880','OPEN'],['Frontier Command','Tau’ri','41','880','470','350','OPEN']]);body='<div class="card wide"><div class="eyebrow">KNOWN REALMS</div><h2>Target board</h2><table class="table"><thead><tr><th>Realm</th><th>Race</th><th>Rank</th><th>Attack</th><th>Defense</th><th>Covert</th><th>Status</th><th>Operation</th></tr></thead><tbody>'+targets.map(t=>'<tr><td><strong>'+t[0]+'</strong></td><td>'+t[1]+'</td><td>#'+t[2]+'</td><td>'+t[3]+'</td><td>'+t[4]+'</td><td>'+t[5]+'</td><td><span class="badge '+(t[6]==='OPEN'?'good':'')+'">'+t[6]+'</span></td><td><button class="button attack-intent" data-action="combat">Attack</button> <button class="button attack-intent" data-action="combat:raid">Raid</button></td></tr>').join('')+'</tbody></table></div><div class="card side-card"><div class="eyebrow">COMBAT PREVIEW</div><h2>Operation costs</h2><div class="row"><span>Attack turns</span><strong>1 per operation</strong></div><div class="row"><span>Fleet readiness</span><strong>850 units</strong></div><div class="row"><span>Expected loot cap</span><strong>10% Naquadah</strong></div><div class="row"><span>Protection check</span><span class="badge good">REQUIRED</span></div></div>';}else if(mode==='attack-log'){body='<div class="card wide"><div class="eyebrow">BATTLE OUTCOMES</div><h2>Recent reports</h2><div class="row"><div><strong>Frontier Command — Victory</strong><small>Attack · 1 turn · 84,000 Naquadah loot</small></div><span class="badge good">UNREAD</span></div><div class="row"><div><strong>Northern Watch — Defense held</strong><small>Raid · 1 turn · 42 attack-unit casualties</small></div><span class="badge">READ</span></div><div class="row"><div><strong>Silent Pattern — Recon acquired</strong><small>Covert intelligence · detection avoided</small></div><span class="badge good">CLASSIFIED</span></div></div><div class="card side-card"><div class="eyebrow">REPORT CONTROLS</div><h2>Audit state</h2><div class="action"><div><strong>Open report</strong><small>Verify recipient ownership and classification.</small></div><button class="button attack-intent" data-action="read_report">Open report</button></div><div class="action"><div><strong>Mark read</strong><small>Update the recipient read state transactionally.</small></div><button class="button attack-intent" data-action="message_read">Mark read</button></div></div>';}else{const type=mode==='spy'?'Spy mission':'Sabotage mission';body='<div class="card wide"><div class="eyebrow">COVERT OPERATIONS</div><h2>'+type+'</h2><div class="metric-grid"><div class="metric"><span>Available agents</span><strong>160</strong><small>Commander covert pool</small></div><div class="metric"><span>Detection formula</span><strong>− agents</strong><small>'+map.formula+'</small></div><div class="metric"><span>Mission state</span><strong>READY</strong><small>Target and ownership validation required</small></div></div><div class="row"><span>Target intelligence</span><strong>Defense, resources, technology</strong></div><div class="row"><span>Detection handling</span><span class="badge">CLASSIFIED REPORT</span></div></div><div class="card side-card"><div class="eyebrow">MISSION CONTROLS</div><h2>Buttons and forms</h2>'+Object.entries(contract.buttons||{}).map(([label,x])=>'<div class="action"><div><strong>'+esc(label)+'</strong><small>'+esc(x.logic)+'</small></div><button class="button attack-intent" data-action="'+esc(x.action)+'">'+esc(label)+'</button></div>').join('')+'<p class="permission">Authenticated commander · agents required · target ownership validated</p></div>';}document.getElementById('content').innerHTML='<div class="cc-grid">'+body+'<div class="card wide"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Attack contract</h2><p class="permission">'+map.formula+'</p>'+['target_realms','players','player_resources','protection_states','battles','battle_reports','covert_missions','intelligence_reports','game_events'].map(x=>'<span class="badge">'+x+'</span> ').join('')+'<p class="permission">All mutations require authentication, CSRF, RBAC, ownership, protection, resource, cooldown, and transaction checks.</p></div><div class="card side-card"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+['ready','protected','insufficient-resource','cooldown','success','error'].map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div><div id="attack-feedback" class="feedback"></div></div>';document.querySelectorAll('.attack-intent').forEach(button=>button.onclick=()=>{const f=document.getElementById('attack-feedback');f.style.display='block';f.textContent='Intent accepted: '+button.dataset.action+' → target/protection/resource validation → deterministic resolver → transactional report.'})}function militaryStatsPage(){const m=state.military||{};const s=state.defcon||{};const formula=m.formula||'power = units × base power × technology × race × government × planet bonus';document.getElementById('section').textContent='COMMAND CENTER';document.getElementById('title').textContent='Military Statistics';document.getElementById('description').textContent='Military Statistics — '+formula;const metric=(label,value,detail)=>'<div class="metric"><span>'+label+'</span><strong>'+(typeof value==='number'?fmt(value):esc(String(value)))+'</strong><small>'+detail+'</small></div>';document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">PAGE DETAILS</div><h2>Military Statistics</h2><p class="permission">'+formula+'</p><div class="metric-grid">'+metric('Attack power',m.attack_power||0,'Units × base power × faction modifiers')+metric('Defense power',m.defense_power||0,'Defense units × shield and government modifiers')+metric('Covert power',m.covert_power||0,'Agents × covert level × faction modifiers')+metric('Anti-covert power',m.anti_covert_power||0,'Counter-agents × anti-covert level × modifiers')+'</div></div><div class="card side-card"><div class="eyebrow">PAGE CONTROLS</div><h2>Buttons and forms</h2><div class="action"><div><strong>View attack</strong><small>Aggregate units, weapons, technologies, race, government, and planet bonuses.</small></div><button class="button military-intent" data-action="read_military_stats">View attack</button></div><div class="action"><div><strong>Set DefCon</strong><small>Validate level, update alert posture, and apply income or defense effects.</small></div><button class="button military-intent" data-action="set_defcon">Set DefCon</button></div><p class="permission">authenticated commander · server-side authority</p><div id="military-feedback" class="feedback"></div></div><div class="card wide"><div class="eyebrow">POWER BREAKDOWN</div><h2>Units and modifiers</h2><div class="row"><span>Attack base</span><strong>'+fmt(m.attack_base||0)+'</strong></div><div class="row"><span>Defense base</span><strong>'+fmt(m.defense_base||0)+'</strong></div><div class="row"><span>Covert base</span><strong>'+fmt(m.covert_base||0)+'</strong></div><div class="row"><span>Anti-covert base</span><strong>'+fmt(m.anti_covert_base||0)+'</strong></div><div class="row"><span>Faction modifiers</span><span class="badge good">'+esc(m.race_name||'Race')+' × '+esc(m.government_name||'Government')+'</span></div></div><div class="card side-card"><div class="eyebrow">READINESS</div><h2>Operational status</h2><div class="metric-grid">'+metric('Readiness',(m.readiness||0)+'%','Attack turns available: '+fmt(m.attack_turns||0))+metric('Attack turns',m.attack_turns||0,'Available offensive operations')+'</div><div class="bar"><i style="width:'+Math.min(100,Math.max(0,Number(m.readiness||0)))+'%"></i></div><p class="permission">Readiness is derived from available attack turns and validated server state.</p></div><div class="card wide"><div class="eyebrow">DEFCON STATE</div><h2>Alert posture</h2><div class="metric-grid">'+metric('Current DefCon',m.defcon_level??s.level??0,'0 = standard posture · 4 = maximum defense')+metric('Cooldown state',m.cooldown_state||s.cooldown_state||'ready',fmt(m.cooldown_remaining_seconds||s.cooldown_remaining_seconds||0)+' seconds remaining')+metric('Server action','set_defcon','Transactional resource and state update')+'</div><div class="row"><span>DefCon effect</span><span class="badge">Defense posture applied server-side</span></div></div><div class="card side-card"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Backend contract</h2><p class="permission">Action: read_military_stats / set_defcon</p>'+['player_resources','player_unit_stats','rankings','protection_states','players','game_events'].map(x=>'<span class="badge">'+x+'</span> ').join('')+'<p class="permission">Read values are authenticated. DefCon changes lock state, validate level and cooldown, update the player, write an event, and commit atomically.</p></div><div class="card wide"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+['ready','protected','cooldown','invalid-input','success','error'].map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></div>';document.querySelectorAll('.military-intent').forEach(button=>button.onclick=()=>{const f=document.getElementById('military-feedback');f.style.display='block';f.textContent='Intent accepted: '+button.dataset.action+' → authentication → RBAC → validation → transactional GameService response.'})}function render(){renderNav((document.getElementById('search').value||'').toLowerCase().trim());if(selected==='dashboard')commandCenter();else if(selected==='account-info')accountInfo();else if(selected==='resources')economyPage();else if(selected==='income')breakdownPage();else if(selected==='military-stats')militaryStatsPage();else if(selected==='sabotage')sabotagePage();else if(selected==='attack-log')reportsPage();else if(selected==='weapons')weaponsPage();else if(['targets','spy'].includes(selected))attackPage(selected);else genericPage()};document.getElementById('search').oninput=()=>render();render();
</script></body></html>
